NEW_MEMORY = '            t = t + cond_hidden + energy_hidden\n            memory_parts = [fused_audio_tokens, traj_memory_tokens]\n            if energy_tokens is not None:\n                memory_parts.append(energy_tokens)\n            memory_parts.append(t_tokens)\n            memory = torch.cat(tuple(memory_parts), dim=-2)\n        else:\n            t = t + cond_hidden + energy_hidden\n            memory_parts = [cond_tokens]\n            if energy_tokens is not None:\n                memory_parts.append(energy_tokens)\n            memory_parts.append(t_tokens)\n            memory = torch.cat(tuple(memory_parts), dim=-2)\n'
GEN_BLOCK_PATTERN = '# ===== TEA-MotionAdapter inference energy helper =====\ndef maybe_attach_energy_condition\\(cond: dict, num_frames: int\\) -> dict:\n.*?\ndef sample_motion\\(model: EDGE, cond: dict, constraint: dict, args, num_frames: int\\):'
GEN_REPLACEMENT = '# ===== TEA-MotionAdapter inference energy helper =====\ndef _env_flag(name: str, default: str = "0") -> bool:\n    return str(os.environ.get(name, default)).strip().lower() in {"1", "true", "yes", "y", "on"}\n\n\ndef _torch_normalize_01(x: torch.Tensor) -> torch.Tensor:\n    x = torch.nan_to_num(x.float(), nan=0.0, posinf=0.0, neginf=0.0)\n    x = x - x.amin(dim=1, keepdim=True)\n    denom = x.amax(dim=1, keepdim=True).clamp_min(1e-8)\n    return x / denom\n\n\ndef _energy_curve_torch_from_cond(cond: dict, num_frames: int) -> torch.Tensor:\n    audio = cond.get("audio", None)\n    traj = cond.get("trajectory", None)\n\n    if audio is None:\n        B = 1 if traj is None else traj.shape[0]\n        device = torch.device("cpu") if traj is None else traj.device\n        return torch.full((B, num_frames, 1), float(os.environ.get("EDGE_ENERGY_LEVEL", "0.55")), device=device)\n\n    audio = audio.float()\n    B, T = audio.shape[0], audio.shape[1]\n    if T != num_frames:\n        audio = F.interpolate(audio.transpose(1, 2), size=num_frames, mode="linear", align_corners=False).transpose(1, 2)\n        T = num_frames\n\n    if audio.shape[-1] > 768:\n        onset = torch.relu(audio[..., 768])\n    elif audio.shape[-1] >= 35:\n        onset = torch.relu(audio[..., 0] + 0.5 * audio[..., -2] + 0.5 * audio[..., -1])\n    else:\n        onset = torch.zeros((B, T), device=audio.device, dtype=audio.dtype)\n        if T > 1:\n            onset[:, 1:] = torch.linalg.norm(audio[:, 1:] - audio[:, :-1], dim=-1)\n            onset[:, 0] = onset[:, 1]\n    onset = _torch_normalize_01(onset)\n\n    if traj is None:\n        speed = torch.zeros_like(onset)\n        curv = torch.zeros_like(onset)\n    else:\n        traj = traj.to(device=audio.device, dtype=audio.dtype)[..., :2]\n        if traj.shape[1] != T:\n            traj = F.interpolate(traj.transpose(1, 2), size=T, mode="linear", align_corners=False).transpose(1, 2)\n\n        speed = torch.zeros((B, T), device=audio.device, dtype=audio.dtype)\n        if T > 1:\n            speed[:, 1:] = torch.linalg.norm(traj[:, 1:] - traj[:, :-1], dim=-1)\n            speed[:, 0] = speed[:, 1]\n        speed = _torch_normalize_01(speed)\n\n        curv = torch.zeros((B, T), device=audio.device, dtype=audio.dtype)\n        if T > 2:\n            v1 = traj[:, 1:-1] - traj[:, :-2]\n            v2 = traj[:, 2:] - traj[:, 1:-1]\n            n1 = torch.linalg.norm(v1, dim=-1)\n            n2 = torch.linalg.norm(v2, dim=-1)\n            cos = (v1 * v2).sum(dim=-1) / (n1 * n2).clamp_min(1e-8)\n            curv[:, 1:-1] = 1.0 - cos.clamp(-1.0, 1.0)\n        curv = _torch_normalize_01(curv)\n\n    w_speed = float(os.environ.get("EDGE_ENERGY_TRAJ_SPEED_WEIGHT", "0.55"))\n    w_audio = float(os.environ.get("EDGE_ENERGY_AUDIO_WEIGHT", "0.30"))\n    w_curv = float(os.environ.get("EDGE_ENERGY_CURVATURE_WEIGHT", "0.15"))\n    total = max(w_speed + w_audio + w_curv, 1e-8)\n\n    base = float(os.environ.get("EDGE_ENERGY_LEVEL", "0.55"))\n    e_min = float(os.environ.get("EDGE_ENERGY_MIN", "0.20"))\n    e_max = float(os.environ.get("EDGE_ENERGY_MAX", "0.85"))\n\n    dynamic = _torch_normalize_01((w_speed * speed + w_audio * onset + w_curv * curv) / total)\n    curve = (0.35 * base + 0.65 * dynamic).clamp(e_min, e_max)\n    return curve.unsqueeze(-1)\n\n\ndef maybe_attach_energy_condition(cond: dict, num_frames: int) -> dict:\n    if not _env_flag("EDGE_ENERGY_COND", "0"):\n        return cond\n\n    if _env_flag("EDGE_ENERGY_TIME_DEPENDENT", "0"):\n        curve = _energy_curve_torch_from_cond(cond, num_frames)\n        cond["energy"] = curve\n        arr = curve.detach().cpu().numpy()\n        print(\n            "✅ TEA time-dependent energy condition: "\n            f"min={arr.min():.3f}, max={arr.max():.3f}, mean={arr.mean():.3f}, "\n            f"cfg_scale={os.environ.get(\'EDGE_ENERGY_CFG_SCALE\', \'default\')}"\n        )\n        return cond\n\n    try:\n        level = float(os.environ.get("EDGE_ENERGY_LEVEL", "0.5"))\n    except Exception:\n        level = 0.5\n    level = float(np.clip(level, 0.0, 1.0))\n    cond["energy"] = torch.full((1, 1), level, dtype=torch.float32)\n    print(f"✅ TEA energy condition: level={level:.3f}, cfg_scale={os.environ.get(\'EDGE_ENERGY_CFG_SCALE\', \'default\')}")\n    return cond\n\n\ndef sample_motion(model: EDGE, cond: dict, constraint: dict, args, num_frames: int):'
TRAJECTORY_HELPER = '\n# ===== Stage A v6: explicit lower-body velocity matching patch =====\ndef _edge_explicit_lower_velocity_loss(diffusion, model_motion_x0, target_motion_x0=None, cond=None):\n    weight = _env_float("EDGE_EXPLICIT_LOWER_VEL_LOSS_WEIGHT", 0.0)\n    if weight <= 0.0:\n        return model_motion_x0.new_tensor(0.0)\n    if model_motion_x0 is None or model_motion_x0.shape[-1] != 151 or model_motion_x0.shape[1] < 2:\n        return model_motion_x0.new_tensor(0.0)\n    try:\n        normalizer = getattr(diffusion, "normalizer", None)\n        physical = maybe_unnormalize(normalizer, model_motion_x0)\n        root = physical[:, :, [diffusion.root_x_idx, diffusion.root_z_idx]]\n        root_speed = torch.linalg.norm(root[:, 1:] - root[:, :-1], dim=-1)\n\n        joints = diffusion._fk_positions(physical)\n        feet = joints[:, :, [7, 8, 10, 11], :]\n        pelvis = physical[:, :, diffusion.root_slice].unsqueeze(2)\n        feet_rel = feet - pelvis\n        lower_rel_speed = torch.linalg.norm(\n            feet_rel[:, 1:, :, [0, 2]] - feet_rel[:, :-1, :, [0, 2]],\n            dim=-1,\n        ).mean(dim=-1)\n\n        threshold = _env_float("EDGE_EXPLICIT_LOWER_ROOT_SPEED_THRESHOLD", 0.006)\n        ratio = _env_float("EDGE_EXPLICIT_LOWER_RELVEL_RATIO", 0.75)\n        min_motion = _env_float("EDGE_EXPLICIT_LOWER_MIN_MOTION", 0.003)\n        gate = root_speed > float(threshold)\n        if not bool(gate.any().item()):\n            return model_motion_x0.new_tensor(0.0)\n        target_lower = min_motion + ratio * root_speed\n        loss = F.relu(target_lower - lower_rel_speed)\n        return loss[gate].mean()\n    except Exception:\n        return model_motion_x0.new_tensor(0.0)\n\n\ndef _edge_add_explicit_loss_to_output(out, extra):\n    if extra is None or not torch.is_tensor(extra):\n        return out\n    if torch.is_tensor(out):\n        return out + extra\n    if isinstance(out, tuple) and len(out) > 0:\n        first = out[0] + extra if torch.is_tensor(out[0]) else out[0]\n        return (first,) + tuple(out[1:])\n    if isinstance(out, list) and len(out) > 0:\n        out = list(out)\n        if torch.is_tensor(out[0]):\n            out[0] = out[0] + extra\n        return out\n    return out\n\n\ndef _edge_patch_explicit_lower_velocity(GaussianDiffusion):\n    if getattr(GaussianDiffusion, "_edge_explicit_lower_velocity_patch_installed", False):\n        return\n    if not hasattr(GaussianDiffusion, "_kinematic_sync_loss"):\n        return\n    original_kinematic_sync_loss = GaussianDiffusion._kinematic_sync_loss\n    def patched_kinematic_sync_loss(self, *args, **kwargs):\n        out = original_kinematic_sync_loss(self, *args, **kwargs)\n        model_motion_x0 = args[0] if args else kwargs.get("model_motion_x0", None)\n        target_motion_x0 = args[1] if len(args) > 1 else kwargs.get("target_motion_x0", None)\n        cond = args[2] if len(args) > 2 else kwargs.get("cond", None)\n        extra = _edge_explicit_lower_velocity_loss(self, model_motion_x0, target_motion_x0=target_motion_x0, cond=cond)\n        weight = _env_float("EDGE_EXPLICIT_LOWER_VEL_LOSS_WEIGHT", 0.0)\n        return _edge_add_explicit_loss_to_output(out, float(weight) * extra)\n    GaussianDiffusion._kinematic_sync_loss = patched_kinematic_sync_loss\n    GaussianDiffusion._edge_original_kinematic_sync_loss = original_kinematic_sync_loss\n    GaussianDiffusion._edge_explicit_lower_velocity_patch_installed = True\n'


def backup(path: Path):
    if not path.exists():
        return
    BACKUP.mkdir(exist_ok=True)
    dst = BACKUP / path.name
    if not dst.exists():
        shutil.copy2(path, dst)
        print(f"📦 backup: {path} -> {dst}")


def write_file(path: Path, text: str):
    backup(path)
    path.write_text(text, encoding="utf-8")
    print(f"✅ wrote: {path}")


def patch_generate_controlled(path: Path):
    backup(path)
    text = path.read_text(encoding="utf-8")
    if "from choreorag_energy_speed import" not in text:
        anchor = "import torch.nn.functional as F\n"
        insert = (
            "import torch.nn.functional as F\n\n"
            "try:\n"
            "    from choreorag_energy_speed import build_energy_curve_from_audio_traj, energy_curve_summary\n"
            "except Exception:\n"
            "    build_energy_curve_from_audio_traj = None\n"
            "    energy_curve_summary = None\n"
        )
        text = text.replace(anchor, insert, 1)
    if "_energy_curve_torch_from_cond" not in text:
        text2 = re.sub(GEN_BLOCK_PATTERN, GEN_REPLACEMENT, text, count=1, flags=re.S)
        if text2 == text:
            raise RuntimeError("Could not patch energy helper block in generate_controlled.py")
        text = text2
    path.write_text(text, encoding="utf-8")
    print(f"✅ patched: {path}")


def patch_model_model(path: Path):
    backup(path)
    text = path.read_text(encoding="utf-8")
    if "energy condition must be [B,1] or [B,T,1]" not in text:
        if OLD_PREPARE not in text:
            raise RuntimeError("Could not patch _prepare_cond_inputs energy block in model/model.py")
        text = text.replace(OLD_PREPARE, NEW_PREPARE, 1)
    if "energy_tokens = None" not in text:
        if OLD_ENERGY not in text:
            raise RuntimeError("Could not patch energy_hidden block in model/model.py")
        text = text.replace(OLD_ENERGY, NEW_ENERGY, 1)
    if "memory_parts = [fused_audio_tokens, traj_memory_tokens]" not in text:
        if OLD_MEMORY not in text:
            raise RuntimeError("Could not patch memory concat block in model/model.py")
        text = text.replace(OLD_MEMORY, NEW_MEMORY, 1)
    path.write_text(text, encoding="utf-8")
    print(f"✅ patched: {path}")


def patch_trajectory_native_control(path: Path):
    backup(path)
    text = path.read_text(encoding="utf-8")
    if "_edge_explicit_lower_velocity_loss" in text:
        print(f"⏭️ already patched: {path}")
        return
    text = text.replace("\ndef install_native_trajectory_control_patch(verbose=True):", TRAJECTORY_HELPER + "\n\ndef install_native_trajectory_control_patch(verbose=True):", 1)
    needle = "    GaussianDiffusion._edge_runtime_safety_patch_installed = True\n"
    if needle not in text:
        raise RuntimeError("Could not find install tail in trajectory_native_control.py")
    text = text.replace(needle, "    _edge_patch_explicit_lower_velocity(GaussianDiffusion)\n\n" + needle, 1)
    path.write_text(text, encoding="utf-8")
    print(f"✅ patched: {path}")


def main():
    if not (ROOT / "EDGE.py").exists() or not (ROOT / "model").is_dir():
        raise SystemExit("Run this script from the EDGE repo root.")
    write_file(ROOT / "choreorag_unit_prior.py", UNIT_PRIOR_CONTENT)
    write_file(ROOT / "choreorag_energy_speed.py", ENERGY_SPEED_CONTENT)
    write_file(ROOT / "make_highenergy_choreo_plan.py", MAKE_PLAN_CONTENT)
    patch_generate_controlled(ROOT / "generate_controlled.py")
    patch_model_model(ROOT / "model" / "model.py")
    patch_trajectory_native_control(ROOT / "trajectory_native_control.py")
    print("\n✅ ChoreoRAG stage patch v2 applied.")
    print("Backups:", BACKUP)
    print("\nSmoke checks:")
    print("  python -m py_compile generate_controlled.py model/model.py trajectory_native_control.py choreorag_unit_prior.py")
    print("  git diff --stat")


if __name__ == "__main__":
    main()
